import time
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3 import pages
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class Diagnostic(pages.Diagnostic):
    """
    The class corresponding to diagnostic page on selenium_sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """
    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._ip_traffic_capturing = IpTrafficCapturingPage(driver, download_checker)
        self._downlink = TestModelsNRDownlinkPage(driver)
        self._uplink = TestModelsNRUplinkPage(driver)
        self._debug_tracing = DebugTracingPage(driver)

    @property
    def ip_traffic_capturing(self):
        return self._ip_traffic_capturing


class TestModelsNRUplinkPage(pages.diagnostic.TestModels5GUplinkPage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Test Models', 'NR Uplink']

    def __init__(self, driver):
        super(TestModelsNRUplinkPage, self).__init__(driver)
        self._view_panel = TestModelsNRUplinkPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_test(self, local_cell, frc_index, reporting_time_interval, timeout=60,
                   physical_cell_id=None, beam_id=None):
        self._view_panel.start_test(local_cell,
                                    frc_index,
                                    reporting_time_interval,
                                    int(timeout),
                                    physical_cell_id,
                                    beam_id)


class TestModelsNRUplinkPageViewPanel(pages.diagnostic.TestModels5GUplinkPageViewPanel):
    _BEAM_ID_INPUT_XPATH = '//div[contains(text(), "Beam pattern ID:")]/parent::*//input'

    def __init__(self, driver):
        super(TestModelsNRUplinkPageViewPanel, self).__init__(driver)

    def _configure_uplink_test(self, local_cell, frc_index, reporting_time_interval,
                               timeout, physical_cell_id=None, beam_id=None):
        super(TestModelsNRUplinkPageViewPanel, self)._configure_uplink_test(local_cell,
                                                                            frc_index,
                                                                            reporting_time_interval,
                                                                            timeout,
                                                                            physical_cell_id)
        if beam_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._BEAM_ID_INPUT_XPATH), str(beam_id), int(timeout))

    def start_test(self, local_cell, frc_index, reporting_time_interval, timeout=60,
                   physical_cell_id=None, beam_id=None):
        self._configure_uplink_test(local_cell,
                                    frc_index,
                                    reporting_time_interval,
                                    timeout,
                                    physical_cell_id,
                                    beam_id)
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)


