class IpTrafficCapturingPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'IP Traffic Capturing']

    def __init__(self, driver, download_checker):
        super(IpTrafficCapturingPage, self).__init__(driver)
        self._ip_traffic_capturing_view_panel = IpTrafficCapturingPageViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_ip_traffic_capturing(self, capture_point='A', include_uplane=True, output=None, timeout=60):
        return self._ip_traffic_capturing_view_panel.start_ip_traffic_capturing(capture_point,
                                                                                include_uplane,
                                                                                output,
                                                                                timeout)

    def stop_ip_traffic_capturing(self, timeout=60):
        return self._ip_traffic_capturing_view_panel.stop_ip_traffic_capturing(timeout)

    def download_ip_traffic_capturing_file(self, download_timeout=60, password=None):
        return self._ip_traffic_capturing_view_panel.download_ip_traffic_capturing_file(download_timeout)


class IpTrafficCapturingPageViewPanel(ViewPanel):
    _CAPTURE_POINT_RAIDO_XPATH = '//div[label[contains(text(), "({})")]]//label'
    _INCLUDE_UPLANE_CHECKBOX_XPATH = '//input[@id="includeUplane"]'
    _INCLUDE_UPLANE_CLICK_XPATH = '//div[input[@id="includeUplane"]]'
    _OUTPUT_RADIO_XPATH = '//div//label[contains(text(), "{}")]'
    _FILE_RADIO = _OUTPUT_RADIO_XPATH.format('File')
    _STREAMING_RADIO_XPATH = _OUTPUT_RADIO_XPATH.format('Streaming')
    _PASSWORD_INPUT_XPATH = '//div[label[contains(text(), "Password")]]//input'
    _EGRESS_PORT_BUTTON_XPATH = '//div[label[contains(text(), "Egress port")]]//button'
    _EGRESS_PORT_VALUE_XPATH = '//div[label[contains(text(), "Egress port")]]//li[@data-value="{}"]'
    _DEST_MAC_ADDR_XPATH = '//div[label[contains(text(), "Destination MAC address")]]//input'
    _FILE = 'File'
    _STREAMING = 'Streaming'
    _START_IP_TRAFFIC_CAPTURING_BUTTON_XPATH = ('//div[contains(@class, "ip-traffic-capturing")]'
                                                '//button[contains(text(), "Start")]')
    _IP_TRAFFIC_CAPTURING_PROGRESS_MEG = '//ip-traffic-capturing-progress-message//span'
    _START_CAPTURING_MSG = 'Start'
    _CAPTURING_COMPLETED_MSG = 'Capturing in file-creation mode'
    _STOP_IP_TRAFFIC_CAPTURING_BUTTON_XPATH = ('//div[contains(@class, "ip-traffic-capturing")]'
                                               '//button[contains(text(), "Stop")]')
    _STOP_CAPTURING_MSG = 'Stop capturing'
    _STOP_COMPLETED_MSG = 'Capturing stopped'
    _DOWNLOAD_FILE_BUTTON_XPATH = ('//div[contains(@class, "ip-traffic-capturing")]'
                                   '//button[contains(text(), "Generate and Download File")]')
    _DOWNLOAD_FILE_COMPLETED = 'Download file complete'

    def __init__(self, driver, download_checker):
        super(IpTrafficCapturingPageViewPanel, self).__init__(driver, download_checker)

    def _select_capture_point(self, capture_point):
        self.click_element_by_xpath(self._CAPTURE_POINT_RAIDO_XPATH.format(capture_point))

    def _select_include_uplane(self, checked):
        self.select_checkbox_by_specified_status(checked,
                                                 self._INCLUDE_UPLANE_CHECKBOX_XPATH,
                                                 self._INCLUDE_UPLANE_CLICK_XPATH)

    def _configure_file_params(self, params):
        password = params.get(self._FILE)
        self.insert_text_to_enable_element((By.XPATH, self._PASSWORD_INPUT_XPATH), password.get('Password', ''))

    def _configure_streaming_params(self, params):
        streaming_params = params.get(self._STREAMING)
        egress_port = streaming_params.get('Egress port')
        self.select_element_from_dropdown_list_by_text_and_click(egress_port,
                                                                 (By.XPATH, self._EGRESS_PORT_BUTTON_XPATH),
                                                                 (By.XPATH,
                                                                  self._EGRESS_PORT_VALUE_XPATH.format(egress_port)))
        dest_mac_addr = streaming_params.get('Destination MAC address')
        self.insert_text_to_enable_element((By.XPATH, self._DEST_MAC_ADDR_XPATH), dest_mac_addr)

    def _configure_ouput(self, output_params):
        if not output_params:
            self.click_enabled_element((By.XPATH, self._FILE_RADIO))
            return

        for k, _ in output_params.items():
            self.click_enabled_element((By.XPATH, self._OUTPUT_RADIO_XPATH.format(k)))
            if k == self._FILE:
                self._configure_file_params(output_params)
                return

            if k == self._STREAMING:
                self._configure_streaming_params(output_params)
                return
        raise AttributeError('param "outpu" should be a dict and have to contain "{}" and "{}"'.format(self._FILE,
                                                                                                       self._STREAMING))

    def start_ip_traffic_capturing(self, capture_point='A', include_uplane=True, output=None, timeout=60):
        self._select_capture_point(capture_point)
        self._select_include_uplane(include_uplane)
        self._configure_ouput(output)
        self.click_enabled_element((By.XPATH, self._START_IP_TRAFFIC_CAPTURING_BUTTON_XPATH), timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._START_CAPTURING_MSG,
                                              timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._CAPTURING_COMPLETED_MSG,
                                              timeout)
        return self.get_text_by_xpath(self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG)

    def stop_ip_traffic_capturing(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._STOP_IP_TRAFFIC_CAPTURING_BUTTON_XPATH))
        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._STOP_CAPTURING_MSG,
                                              timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._STOP_COMPLETED_MSG,
                                              timeout)
        return self.get_text_by_xpath(self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG)

    def download_ip_traffic_capturing_file(self, download_timeout=60):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._DOWNLOAD_FILE_BUTTON_XPATH), download_timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._DOWNLOAD_FILE_COMPLETED,
                                              download_timeout)
        return self.download_files(start_time, download_timeout)


class DebugTracingPage(pages.diagnostic.DebugTracingPage):
    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)


class DebugTracingPageViewPanel(pages.diagnostic.DebugTracingPageViewPanel):
    _UPLANE_COMPONENT_SELECT_ALL_CELLS_XPATH = ('//section[@class="uPlane-component"]//div[@class="select-cells-type"]'
                                                '//label[contains(text(), "Select all")]')
    _UPLANE_COMPONENT_SELECT_MAX_CELLS_XPATH = ('//section[@class="uPlane-component"]//div[@class="select-cells-type"]'
                                                '//label[contains(text(), "Select max")]')
    _UPLANE_SHERPA_SELECT_ALL_CELLS_XPATH = ('//u-plane-sherpa//div[@class="select-cells-type"]'
                                             '//label[contains(text(), "Select all")]')
    _UPLANE_SHERPA_SELECT_MAX_CELLS_XPATH = ('//u-plane-sherpa//div[@class="select-cells-type"]'
                                             '//label[contains(text(), "Select max")]')

    _MODULE_SELECT_CELLS_MAPPING = {
        'u-plane-component': [_UPLANE_COMPONENT_SELECT_ALL_CELLS_XPATH, _UPLANE_COMPONENT_SELECT_MAX_CELLS_XPATH],
        'u-plane-sherpa': [_UPLANE_SHERPA_SELECT_ALL_CELLS_XPATH, _UPLANE_SHERPA_SELECT_MAX_CELLS_XPATH]
    }

    _TARGET_MODULE_DROPDOWN_BUTTON_XPATH = ('//section[@class="uPlane-component"]//div[contains(text(), '
                                            '"Target module")]/following-sibling::div//button')
    _TARGET_MODULE_DROPDOWN_LIST_XPATH = ('//section[@class="uPlane-component"]//div[contains(text(), '
                                          '"Target module")]/following-sibling::div//ul//a//span')
    _CPLANE_START_DU_TRACES_BUTTON_XPATH = '//cplane//ui-button[@a-text="Configure"]//button'
    _CPLANE_TRACE_STARTING_STATUS = 'Configuring...'

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def _choose_bbmod(self, bbmod):
        self.select_element_from_dropdown_list_by_text_and_click(bbmod,
                                                                 (By.XPATH, self._TARGET_MODULE_DROPDOWN_BUTTON_XPATH),
                                                                 (By.XPATH, self._TARGET_MODULE_DROPDOWN_LIST_XPATH))

    def start_cplane_du_traces(self, timeout=60):
        """
        Method for starting cplane du traces
        """
        self.click_enabled_element((By.XPATH, self._CPLANE_START_DU_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._CPLANE_TYPE, timeout)

    def _get_tracing_result(self, module_type, timeout=60):
        error_info = self._return_error_if_configure_modal_exist()
        if error_info:
            return error_info

        module_type_mapping_dict = {
            self._COMPONENT_TYPE: self._COMPONENT_TRACE_STATUS_XPATH,
            self._SHERPA_TYPE: self._SHERPA_TRACE_STATUS_XPATH,
            self._CPLANE_TYPE: self._CPLANE_TRACE_STATUS_XPATH
        }

        tracing_middle_status = (self._CPLANE_TRACE_STARTING_STATUS
                                 if module_type == self._CPLANE_TYPE else self._TRACE_STARTING_STATUS)

        return self._get_trace_status_after_start_or_stop(module_type_mapping_dict[module_type],
                                                          tracing_middle_status,
                                                          timeout)

    def _choose_cells(self, cells_list, module_type, timeout=60):
        choose_cells_way = self._MODULE_SELECT_CELLS_MAPPING[module_type]
        if not cells_list:
            self.click_enabled_element((By.XPATH, choose_cells_way[0]))
        else:
            self.click_enabled_element((By.XPATH, choose_cells_way[1]))
            for index, cell_text in enumerate(cells_list):
                self.select_element_from_dropdown_list_by_text_and_click(
                    cell_text,
                    (By.XPATH, self._CELLS_BUTTON_XPATH.format(module_type, index + 1)),
                    (By.XPATH, self._CELLS_OPTION_XPATH.format(module_type, index + 1)),
                    timeout
                )
